        section: {
          id: section.id,
          name: section.name,
          classBn: section.class_bn,
          group: section.group,
          yearLabel: section.year_label,
          capacity: section.capacity,
          currentCount: section.student_count,
          countAfter: willBe
        },
        moving: plan2,
        alreadyInSection: alreadyHere.map((r) => ({ studentId: r.student_id, nameBn: r.name_bn })),
        notFound: missing,
